import os
from typing import Any, Dict, List

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


AZURE_FORM_RECOGNIZER_ENDPOINT = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
AZURE_FORM_RECOGNIZER_KEY = os.environ["AZURE_FORM_RECOGNIZER_KEY"]
AZURE_FORM_RECOGNIZER_MODEL = "prebuilt-layout"


def extract_tables_and_rows(document_path: str) -> List[Dict[str, Any]]:
    client = DocumentAnalysisClient(
        endpoint=AZURE_FORM_RECOGNIZER_ENDPOINT,
        credential=AzureKeyCredential(AZURE_FORM_RECOGNIZER_KEY),
    )

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(
            AZURE_FORM_RECOGNIZER_MODEL,
            document=f,
        )
        result = poller.result()

    tables_output: List[Dict[str, Any]] = []

    for table_index, table in enumerate(result.tables):
        row_map: Dict[int, List[Dict[str, Any]]] = {}

        for cell in table.cells:
            cell_data = {
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "row_span": cell.row_span or 1,
                "column_span": cell.column_span or 1,
                "content": cell.content,
                "kind": getattr(cell, "kind", None),
                "bounding_regions": [
                    {
                        "page_number": br.page_number,
                        "polygon": br.polygon,
                    }
                    for br in (cell.bounding_regions or [])
                ],
                "spans": [
                    {
                        "offset": span.offset,
                        "length": span.length,
                    }
                    for span in (cell.spans or [])
                ],
            }
            row_map.setdefault(cell.row_index, []).append(cell_data)

        rows: List[Dict[str, Any]] = []
        for row_index in sorted(row_map):
            sorted_cells = sorted(row_map[row_index], key=lambda c: c["column_index"])
            rows.append(
                {
                    "row_index": row_index,
                    "cells": sorted_cells,
                }
            )

        tables_output.append(
            {
                "table_index": table_index,
                "row_count": table.row_count,
                "column_count": table.column_count,
                "bounding_regions": [
                    {
                        "page_number": br.page_number,
                        "polygon": br.polygon,
                    }
                    for br in (table.bounding_regions or [])
                ],
                "rows": rows,
            }
        )

    return tables_output
